from aide import L, st, e, v, d, ch, li, od

UNIT = ("Culture et références", "🎭", "Comprendre les références culturelles des anglophones.", [

L("📜", "Shakespeare et la Bible au quotidien",
  "Reconnaître les expressions venues de Shakespeare et de la Bible.",
  [st("📜", "Shakespeare a inventé ou popularisé des centaines d’expressions encore utilisées : break the ice, wild-goose chase, in a pickle, wear your heart on your sleeve."),
   st("📖", "La Bible a aussi laissé des expressions courantes, même chez les non-croyants : a good Samaritan, the writing on the wall, go the extra mile, a labor of love."),
   st("🎯", "Sens : wild-goose chase (recherche inutile), in a pickle (dans le pétrin), the writing on the wall (signe annonciateur d’un échec)."),
   st("💬", "Elles s’utilisent sans aucune connotation religieuse ou littéraire.")],
  [e("🦢", "Looking for parking downtown is a wild-goose chase.", "Chercher du stationnement au centre-ville, c’est peine perdue."),
   e("🥒", "I’m in a bit of a pickle: I locked my keys in the car.", "Je suis dans le pétrin : j’ai barré mes clés dans l’auto."),
   e("🧱", "When sales dropped, the writing was on the wall.", "Quand les ventes ont chuté, les signes étaient clairs."),
   e("🤝", "A good Samaritan helped me change my tire.", "Un bon Samaritain m’a aidé à changer mon pneu."),
   e("🏃", "She always goes the extra mile for her clients.", "Elle en fait toujours plus pour ses clients.")],
  [v("🦢", "a wild-goose chase", "une recherche vaine", "It was a wild-goose chase."),
   v("🥒", "in a pickle", "dans le pétrin", "We’re in a pickle."),
   v("🧱", "the writing on the wall", "les signes avant-coureurs", "I saw the writing on the wall."),
   v("🤝", "a good Samaritan", "un bon Samaritain", "Thanks, good Samaritan!"),
   v("🏃", "go the extra mile", "faire un effort supplémentaire", "He went the extra mile."),
   v("❤️", "wear your heart on your sleeve", "être à fleur de peau, montrer ses émotions", "She wears her heart on her sleeve.")],
  [d("Kim", "How was your search for the vintage lamp?", "Comment s’est passée ta recherche de la lampe vintage?"),
   d("Raf", "A total wild-goose chase. Six stores, nothing!", "Peine perdue. Six magasins, rien!"),
   d("Kim", "Too bad. You really go the extra mile for your decor.", "Dommage. Tu fais vraiment des efforts pour ta déco."),
   d("Raf", "I know. I wear my heart on my sleeve when it comes to design!", "Je sais. Je suis passionné quand il s’agit de design!")],
  "Ces expressions sont un code culturel : les comprendre te fait entrer dans les conversations, les blagues et les articles des anglophones.",
  [ch("Searching for something that doesn’t exist is a ___ chase.", ["wild-goose", "wild-duck", "crazy-goose"], 0, "a wild-goose chase."),
   ch("« Être dans le pétrin » = to be in a ___.", ["pickle", "jam jar", "pepper"], 0, "in a pickle."),
   ch("He always does more than required. He goes the extra ___.", ["mile", "step", "way"], 0, "go the extra mile."),
   ch("A stranger who helps you is a good ___.", ["Samaritan", "neighbor", "angel"], 0, "a good Samaritan."),
   li("The writing was on the wall.", ["The writing was on the wall.", "The writing was on the hall.", "The writing is on the wall."], 0, "Signes annonciateurs."),
   od("She always goes the extra mile", "Elle en fait toujours plus", "go the extra mile.")]),

L("🏒", "Les métaphores sportives",
  "Comprendre les métaphores tirées du hockey, du baseball et du football.",
  [st("⚾", "Baseball : a ballpark figure (une estimation), step up to the plate (prendre ses responsabilités), out of left field (inattendu), touch base (faire un suivi)."),
   st("🏈", "Football : a game plan (un plan d’action), drop the ball (échapper le ballon, faire une erreur), Monday-morning quarterback (gérant d’estrade)."),
   st("🏀", "Basketball : a slam dunk (une victoire facile, une évidence), full-court press (pression maximale)."),
   st("🏒", "Hockey (très canadien) : hat trick (trois réussites), drop the gloves (se préparer à se battre), a power play (un avantage stratégique).")],
  [e("⚾", "Can you give me a ballpark figure?", "Peux-tu me donner une estimation approximative?"),
   e("🏈", "Sorry, I dropped the ball on that email.", "Désolé, j’ai échappé ce courriel."),
   e("🏀", "With her experience, the promotion is a slam dunk.", "Avec son expérience, la promotion est dans la poche."),
   e("⚾", "Let’s touch base next week.", "Faisons un suivi la semaine prochaine."),
   e("🏒", "Three sales in one day — that’s a hat trick!", "Trois ventes en une journée, c’est un tour du chapeau!")],
  [v("⚾", "a ballpark figure", "une estimation approximative", "Give me a ballpark figure."),
   v("🏈", "drop the ball", "échapper le ballon, faire une erreur", "Who dropped the ball?"),
   v("🏀", "a slam dunk", "une affaire dans le sac", "This deal is a slam dunk."),
   v("⚾", "touch base", "faire un suivi, prendre contact", "Let’s touch base tomorrow."),
   v("⚾", "step up to the plate", "prendre ses responsabilités", "It’s time to step up to the plate."),
   v("🏒", "hat trick", "tour du chapeau", "She scored a hat trick.")],
  [d("Client", "How much would the renovation cost? Just a ballpark figure.", "Combien coûteraient les rénovations? Juste une estimation."),
   d("Contractor", "Roughly forty thousand.", "Environ quarante mille."),
   d("Client", "Okay. Let’s touch base after I talk to my wife.", "D’accord. On se reparle quand j’en aurai discuté avec ma femme."),
   d("Contractor", "Sounds good. I won’t drop the ball on the quote.", "Parfait. Je ne vais pas échapper la soumission.")],
  "Les Américains utilisent surtout des métaphores de baseball et de football; les Canadiens ajoutent celles du hockey. Toutes sont très courantes au bureau.",
  [ch("Can you give me a ___ figure? (approximatif)", ["ballpark", "baseball", "stadium"], 0, "a ballpark figure."),
   ch("I forgot to send the report. I dropped the ___.", ["ball", "puck", "bat"], 0, "drop the ball."),
   ch("Getting the contract will be easy. It’s a slam ___.", ["dunk", "shot", "goal"], 0, "a slam dunk."),
   ch("Let’s touch ___ on Monday.", ["base", "ground", "basis"], 0, "touch base = faire un suivi."),
   li("Let’s touch base next week.", ["Let’s touch base next week.", "Let’s touch base next month.", "Let’s touch base last week."], 0, "touch base."),
   od("Can you give me a ballpark figure", "Peux-tu me donner une estimation approximative?", "a ballpark figure.")]),

L("🗞️", "Proverbes et dictons",
  "Comprendre les proverbes, même quand on n’en dit que la moitié.",
  [st("🗞️", "Les anglophones citent souvent un proverbe à moitié, sachant que l’autre le complètera : « When in Rome… » (…do as the Romans do)."),
   st("📚", "Autres : The early bird… (catches the worm), Don’t count your chickens… (before they hatch), Speak of the devil… (and he shall appear)."),
   st("🔁", "Équivalents français : The early bird catches the worm = l’avenir appartient à ceux qui se lèvent tôt. Don’t count your chickens… = il ne faut pas vendre la peau de l’ours…"),
   st("💬", "« Speak of the devil! » s’utilise quand la personne dont on parle arrive.")],
  [e("🏛️", "We eat dinner at 10 p.m. here. When in Rome…", "Ici, on soupe à 22 h. À Rome, fais comme les Romains…"),
   e("🐦", "I’m at the gym at 6 a.m. The early bird catches the worm!", "Je suis au gym à 6 h. L’avenir appartient à ceux qui se lèvent tôt!"),
   e("🐣", "Don’t count your chickens before they hatch.", "Il ne faut pas vendre la peau de l’ours avant de l’avoir tué."),
   e("😈", "Speak of the devil! Hi, Marc!", "Quand on parle du loup! Salut, Marc!"),
   e("🍳", "You can’t make an omelet without breaking eggs.", "On ne fait pas d’omelette sans casser des œufs.")],
  [v("🏛️", "When in Rome, do as the Romans do", "À Rome, fais comme les Romains", "When in Rome…"),
   v("🐦", "The early bird catches the worm", "L’avenir appartient à ceux qui se lèvent tôt", "The early bird…"),
   v("🐣", "Don’t count your chickens before they hatch", "Ne vends pas la peau de l’ours…", "Don’t count your chickens."),
   v("😈", "Speak of the devil", "Quand on parle du loup", "Speak of the devil!"),
   v("🧺", "Don’t put all your eggs in one basket", "Ne mets pas tous tes œufs dans le même panier", "Diversify: don’t put all your eggs in one basket."),
   v("📜", "proverb / saying", "proverbe / dicton", "an old saying")],
  [d("Ana", "I’m sure I’ll get the promotion. I already bought a new car!", "Je suis sûre d’avoir la promotion. J’ai déjà acheté une auto neuve!"),
   d("Ben", "Whoa, don’t count your chickens…", "Wow, ne vends pas la peau de l’ours…"),
   d("Ana", "You’re right. Oh, speak of the devil — here’s my boss!", "Tu as raison. Oh, quand on parle du loup, voici ma patronne!"),
   d("Ben", "Good luck!", "Bonne chance!")],
  "Les proverbes anglais et français se ressemblent souvent par le sens mais pas par l’image : la peau de l’ours devient des poussins, le loup devient le diable.",
  [ch("Your colleague arrives as you talk about him: « Speak of the ___! »", ["devil", "wolf", "angel"], 0, "Speak of the devil!"),
   ch("« The early ___ catches the worm. »", ["bird", "cat", "fish"], 0, "The early bird catches the worm."),
   ch("« Don’t count your ___ before they hatch. »", ["eggs", "chickens", "birds"], 1, "chickens."),
   ch("« When in Rome, do as the ___ do. »", ["Italians", "Romans", "locals"], 1, "Romans."),
   li("Don’t put all your eggs in one basket.", ["Don’t put all your eggs in one basket.", "Don’t put all your eggs in one bucket.", "Don’t put all your legs in one basket."], 0, "Diversifier."),
   od("Speak of the devil here comes Marc", "Quand on parle du loup, voici Marc", "Speak of the devil.")]),

L("🎬", "L’humour et les jeux de mots",
  "Comprendre les jeux de mots (puns) et l’humour culturel.",
  [st("🎬", "Un pun joue sur un mot à double sens ou sur deux mots qui sonnent pareil : « I used to be a baker, but I couldn’t make enough dough » (dough = pâte ET argent)."),
   st("👨‍👧", "Les « dad jokes » sont des blagues de papa, volontairement mauvaises, souvent des puns. On y répond par un soupir (groan)."),
   st("📺", "Les pubs et les titres adorent les puns : « Time to make a splash » (piscine), « Lettuce celebrate » (laitue = let us)."),
   st("🧠", "Pour les comprendre : cherche le mot qui a deux sens ou qui sonne comme un autre mot.")],
  [e("🍞", "I used to be a baker, but I couldn’t make enough dough.", "J’étais boulanger, mais je ne faisais pas assez de « blé »."),
   e("🥬", "Lettuce celebrate!", "Célébrons! (laitue = let us)"),
   e("⏰", "I’m reading a book about anti-gravity. It’s impossible to put down.", "Je lis un livre sur l’antigravité. Impossible de le poser!"),
   e("🐻", "I can’t bear it!", "Je ne peux pas le supporter! (bear = ours / supporter)"),
   e("😩", "Ugh, that’s such a dad joke.", "Ouf, c’est vraiment une blague de mononcle.")],
  [v("🎬", "pun", "jeu de mots", "That’s a terrible pun!"),
   v("👨‍👧", "dad joke", "blague de mononcle", "My dad loves dad jokes."),
   v("😩", "groan", "grogner, soupirer", "Everyone groaned at the joke."),
   v("🔀", "double meaning", "double sens", "The word has a double meaning."),
   v("🍞", "dough", "pâte; argent (familier)", "He makes a lot of dough."),
   v("🎯", "punchline", "chute (d’une blague)", "I didn’t get the punchline.")],
  [d("Dad", "Why don’t skeletons fight each other?", "Pourquoi les squelettes ne se battent-ils pas?"),
   d("Teen", "I don’t know. Why?", "Je ne sais pas. Pourquoi?"),
   d("Dad", "They don’t have the guts!", "Ils n’ont pas de cran! (guts = tripes / courage)"),
   d("Teen", "Ugh, Dad. That’s the worst dad joke ever.", "Ouf, papa. C’est la pire blague de mononcle.")],
  "Comprendre un jeu de mots est un excellent test de niveau C2 : il faut connaître les deux sens du mot ET la culture.",
  [ch("« I couldn’t make enough dough » is funny because dough means pastry and ___.", ["money", "flour", "time"], 0, "dough = argent (familier)."),
   ch("A joke based on a word with two meanings is a ___.", ["pun", "punch", "punchline"], 0, "pun = jeu de mots."),
   ch("« Lettuce celebrate » sounds like « ___ celebrate ».", ["let us", "let’s us", "lets"], 0, "lettuce = let us."),
   ch("The funny last line of a joke is the ___.", ["punchline", "headline", "pun"], 0, "punchline = chute."),
   li("It’s impossible to put down.", ["It’s impossible to put down.", "It’s impossible to put up.", "It’s impossible to pull down."], 0, "Jeu sur gravité / poser."),
   od("That is the worst dad joke ever", "C’est la pire blague de mononcle", "dad joke.")]),

L("🍁", "L’anglais du Canada",
  "Connaître les particularités de l’anglais canadien.",
  [st("🍁", "Vocabulaire canadien : toque/tuque (tuque), loonie (pièce de 1 $), toonie (2 $), washroom (toilettes), double-double (café 2 crèmes 2 sucres), chesterfield (divan, vieilli)."),
   st("✍️", "Orthographe mixte : britannique pour -our et -re (colour, centre), américaine pour -ize (organize) et certains mots (tire, pas tyre)."),
   st("👂", "Prononciation : « about » et « house » avec une voyelle particulière (le « Canadian raising »), Z = « zed »."),
   st("🙏", "Culture : politesse légendaire (sorry partout), « eh? » pour chercher l’approbation, fierté du hockey et de la diversité.")],
  [e("☕", "I’ll have a double-double, please.", "Je vais prendre un café deux crèmes deux sucres, s’il vous plaît."),
   e("🪙", "Do you have a toonie for the parking meter?", "As-tu une pièce de deux dollars pour le parcomètre?"),
   e("🧢", "Don’t forget your toque, it’s minus twenty.", "N’oublie pas ta tuque, il fait moins vingt."),
   e("🙏", "Sorry! — No, I’m sorry!", "Désolé! — Non, c’est moi qui suis désolé!"),
   e("🍁", "Great game last night, eh?", "Super match hier soir, hein?")],
  [v("🪙", "loonie / toonie", "pièce de 1 $ / 2 $", "Pay with a loonie."),
   v("☕", "double-double", "café deux crèmes deux sucres", "A large double-double."),
   v("🧢", "toque / tuque", "tuque", "Wear a toque."),
   v("🚻", "washroom", "toilettes", "The washroom is upstairs."),
   v("🍁", "eh?", "hein? (Canada)", "It’s cold, eh?"),
   v("🏒", "rink", "patinoire", "Let’s go to the rink.")],
  [d("Tourist", "What’s a « double-double »?", "C’est quoi un « double-double »?"),
   d("Barista", "Coffee with two creams and two sugars. Very Canadian!", "Un café avec deux crèmes et deux sucres. Très canadien!"),
   d("Tourist", "I’ll try one. Can I pay with this coin?", "Je vais en essayer un. Puis-je payer avec cette pièce?"),
   d("Barista", "That’s a toonie, so yes! Enjoy, eh!", "C’est un « toonie », alors oui! Bonne dégustation!")],
  "Pour un francophone du Québec, l’anglais canadien est le plus utile au quotidien : mêmes réalités (la tuque, la patinoire, l’hiver) et mêmes institutions.",
  [ch("A Canadian two-dollar coin is a ___.", ["loonie", "toonie", "twoonie"], 1, "toonie = 2 $."),
   ch("Coffee with two creams and two sugars is a ___.", ["double-double", "two-two", "double cream"], 0, "double-double."),
   ch("Canadian spelling: ___", ["color", "colour", "coller"], 1, "colour (orthographe britannique)."),
   ch("In Canada, the letter Z is called ___.", ["zee", "zed", "zeta"], 1, "zed."),
   li("Great game last night, eh?", ["Great game last night, eh?", "Great game last night, hey?", "Great gain last night, eh?"], 0, "eh? canadien."),
   od("Do you have a toonie for parking", "As-tu une pièce de deux dollars pour le stationnement?", "toonie = 2 $.")]),
])
